  interface

    !---------------------------------------------
    ! hipblasCreate
    !---------------------------------------------
    !>  \brief Create the hipBLAS handle.
    function hipblasCreate(handle) &
       result(Create) &
       bind(C, name="hipblasCreate")
       import :: c_ptr, HIPBLAS_STATUS_SUCCESS
       type(c_ptr) :: handle
       integer(kind(HIPBLAS_STATUS_SUCCESS)) :: Create
    end function hipblasCreate

    !---------------------------------------------
    ! hipblasDestroy
    !---------------------------------------------
    !>  \brief Destroys the library context created using hipblasCreate().
    function hipblasDestroy(handle) &
       result(Destroy) &
       bind(C, name="hipblasDestroy")
       import :: c_ptr, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
       integer(kind(HIPBLAS_STATUS_SUCCESS)) :: Destroy
    end function hipblasDestroy

    !---------------------------------------------
    ! hipblasGetVersion
    !---------------------------------------------
    !>  \brief Gets the hipBLAS library version number.
    !>     \details
    !>     Returns version as integer: major * 10000 + minor * 100 + patch.
    !>     Example: version 3.5.1 returns 30501.
    !>
    !>     Handle parameter can be NULL.
    !>
    !>     @param[in] handle - Handle to library context (can be NULL)
    !>     @param[out] version - Pointer to integer for version number
    !>
    !>     @return HIPBLAS_STATUS_SUCCESS or HIPBLAS_STATUS_INVALID_VALUE if version is NULL
    function hipblasGetVersion(handle, version) &
       result(GetVersion) &
       bind(C, name="hipblasGetVersion")
       import :: c_ptr, c_int, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
       integer(c_int) :: version
       integer(kind(HIPBLAS_STATUS_SUCCESS)) :: GetVersion
    end function hipblasGetVersion

    !---------------------------------------------
    ! hipblasGetProperty
    !---------------------------------------------
    !>  \brief Gets a specific property of the hipBLAS library.
    !>     \details
    !>     Returns requested property value (major, minor, or patch).
    !>     Does not require a handle.
    !>
    !>     @param[in] myType - Property type to query
    !>     @param[out] myValue - Pointer to integer for property value
    !>
    !>     @return HIPBLAS_STATUS_SUCCESS or HIPBLAS_STATUS_INVALID_VALUE
    function hipblasGetProperty(myType, myValue) &
       result(GetProperty) &
       bind(C, name="hipblasGetProperty")
       import :: HIPBLAS_MAJOR_VERSION, c_ptr, HIPBLAS_STATUS_SUCCESS
       integer(kind(HIPBLAS_MAJOR_VERSION)), value :: myType
       type(c_ptr), value :: myValue
       integer(kind(HIPBLAS_STATUS_SUCCESS)) :: GetProperty
    end function hipblasGetProperty

