    !---------------------------------------------
    ! hipblasChprBatched_64
    !---------------------------------------------
    function hipblasChprBatched_64(handle, uplo, n, alpha, x, incx, AP, batchCount) &
       result(ChprBatched_64) &
       bind(C, name="hipblasChprBatched_64")
       import :: c_ptr, HIPBLAS_FILL_MODE_UPPER, c_int64_t, c_float, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
