    !---------------------------------------------
    ! hipblasSsymvBatched
    !---------------------------------------------
    !>     \brief  BLAS Level 2 API
    !>
    !>     \details
    !>     symvBatched performs the matrix-vector operation:
    !>
    !>         y_i := alpha*A_i*x_i + beta*y_i,
    !>
    !>     where ``(A_i, x_i, y_i)`` is the ``i``-th instance of the batch,
    !>     ``alpha`` and ``beta`` are scalars, ``x_i`` and ``y_i`` are vectors, and ``A_i`` is an
    !>     n by n symmetric matrix, for ``i`` = 1, ..., ``batchCount``.
    !>     ``A`` should contain an upper or lower triangular symmetric matrix.
    !>     The opposing triangular part of ``A`` is not referenced.
    !>
    !>     - Supported precisions in rocBLAS : ``s``, ``d``, ``c``, and ``z``.
    !>     - Supported precisions in cuBLAS  : No support.
    !>
    !>     @param[in] handle - [hipblasHandle_t]
    !>               handle to the hipBLAS library context queue.
    !>     @param[in] uplo - [hipblasFillMode_t]
    !>               specifies either upper (HIPBLAS_FILL_MODE_UPPER) or lower
    !>               (HIPBLAS_FILL_MODE_LOWER):
    !>               - If HIPBLAS_FILL_MODE_UPPER, the lower part of A is not referenced.
    !>               - If HIPBLAS_FILL_MODE_LOWER, the upper part of A is not referenced.
    !>     @param[in] n - [int]
    !>               number of rows and columns of each matrix A_i.
    !>     @param[in] alpha
    !>               device pointer or host pointer to scalar alpha.
    !>     @param[in] AP - device array of device pointers storing each matrix A_i.
    !>     @param[in] lda - [int]
    !>               specifies the leading dimension of each matrix A_i.
    !>     @param[in] x - device array of device pointers storing each vector x_i.
    !>     @param[in] incx - [int]
    !>               specifies the increment for the elements of each vector x_i.
    !>     @param[in] beta - device pointer or host pointer to scalar beta.
    !>     @param[out] y - device array of device pointers storing each vector y_i.
    !>     @param[in] incy - [int]
    !>               specifies the increment for the elements of each vector y_i.
    !>     @param[in] batchCount - [int]
    !>                 number of instances in the batch.
    function hipblasSsymvBatched(handle, uplo, n, alpha, AP, lda, x, incx, beta, y, incy, &
                                 batchCount) &
       result(SsymvBatched) &
       bind(C, name="hipblasSsymvBatched")
       import :: c_ptr, HIPBLAS_FILL_MODE_UPPER, c_int, c_float, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
       integer(kind(HIPBLAS_FILL_MODE_UPPER)), value :: uplo
       integer(c_int), value :: n
       real(c_float) :: alpha
       type(c_ptr), value :: AP
       integer(c_int), value :: lda
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       real(c_float) :: beta
       type(c_ptr), value :: y
       integer(c_int), value :: incy
       integer(c_int), value :: batchCount
       integer(kind(HIPBLAS_STATUS_SUCCESS)) :: SsymvBatched
    end function hipblasSsymvBatched

    !---------------------------------------------
    ! hipblasDsymvBatched
    !---------------------------------------------
    function hipblasDsymvBatched(handle, uplo, n, alpha, AP, lda, x, incx, beta, y, incy, &
                                 batchCount) &
       result(DsymvBatched) &
       bind(C, name="hipblasDsymvBatched")
       import :: c_ptr, HIPBLAS_FILL_MODE_UPPER, c_int, c_double, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
       integer(kind(HIPBLAS_FILL_MODE_UPPER)), value :: uplo
       integer(c_int), value :: n
       real(c_double) :: alpha
       type(c_ptr), value :: AP
       integer(c_int), value :: lda
       type(c_ptr), value :: x
