    !---------------------------------------------
    function hipblasCdgmmBatched(handle, side, m, n, AP, lda, x, incx, CP, ldc, batchCount) &
       result(CdgmmBatched) &
       bind(C, name="hipblasCdgmmBatched")
       import :: c_ptr, HIPBLAS_SIDE_LEFT, c_int, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
