    !---------------------------------------------
    ! hipblasDgelsStridedBatched
    !---------------------------------------------
    function hipblasDgelsStridedBatched(handle, trans, m, n, nrhs, A, lda, strideA, B, ldb, &
                                        strideB, myInfo, deviceInfo, batchCount) &
       result(DgelsStridedBatched) &
       bind(C, name="hipblasDgelsStridedBatched")
       import :: c_ptr, HIPBLAS_OP_N, c_int, c_int64_t, HIPBLAS_STATUS_SUCCESS
       type(c_ptr), value :: handle
       integer(kind(HIPBLAS_OP_N)), value :: trans
